mapper.select:
SELECT TOP (#{query.limit}) id, occurred_at, actor_user_id, actor_login_snapshot, organization_id,
       organization_code_snapshot, action_code, target_type, target_id, result_code,
       change_summary, request_id
FROM audit_management_event
WHERE (organization_code_snapshot IS NULL

        OR organization_code_snapshot IN
        #{code}

)
AND actor_login_snapshot = #{query.actorLogin}
AND action_code = #{query.actionCode}
AND target_type = #{query.targetType}
AND target_id = #{query.targetId}
AND request_id = #{query.requestId}
AND result_code = #{query.resultCode}
AND occurred_at >= #{query.occurredFrom}
AND occurred_at <= #{query.occurredTo}

    AND (occurred_at < #{query.beforeOccurredAt}
        OR (occurred_at = #{query.beforeOccurredAt} AND id < #{query.beforeId}))

ORDER BY occurred_at DESC, id DESC
